import com.bridger.momentum.*;
import java.nio.file.*;
import javax.sound.sampled.*;
public final class ClipAudioMixRegression {
 public static void main(String[] args)throws Exception{if(!NativeClipTools.windows())return;Path folder=Files.createTempDirectory("audio-mix-");long start=1000000000L;Path[] files={folder.resolve("output.wav"),folder.resolve("microphone.wav")};for(int source=0;source<2;source++){byte[] pcm=new byte[96000];for(int i=0;i<48000;i++){short value=(short)(Math.sin(i*2*Math.PI*(source==0?440:880)/48000)*8000);pcm[2*i]=(byte)value;pcm[2*i+1]=(byte)(value>>8);}ClipPcmBuffer buffer=new ClipPcmBuffer(48000);buffer.add(start+1000000000L,pcm,pcm.length);buffer.wave(start,start+1000000000L,files[source]);}Path mixed=ClipAudioMix.mix(files[0],files[1],folder);try(AudioInputStream audio=AudioSystem.getAudioInputStream(mixed.toFile())){if(audio.getFrameLength()<47900||audio.getFormat().getChannels()!=2)throw new AssertionError("Mixed audio duration/channels invalid");byte[] pcm=new byte[192000];int total=0,n;while(total<pcm.length&&(n=audio.read(pcm,total,pcm.length-total))>0)total+=n;for(int hz:new int[]{440,880}){double energy=0;for(int i=0;i<total/4;i++){short sample=(short)((pcm[4*i]&255)|(pcm[4*i+1]<<8));energy+=sample*Math.sin(i*2*Math.PI*hz/48000);}if(Math.abs(energy)/(total/4)<1000)throw new AssertionError("An audio source disappeared from the mix: "+hz);}}System.out.println("PASS: real FFmpeg mix preserves system and microphone frequencies with exact stereo duration; no device recorded");}
}
